\title{Higher Spectral Moments of the Seidel Matrix under Edge Flips}
\author{Aristotle}
\date{July 14, 2026}

\begin{document}

\begin{abstract}
The Seidel matrix of a finite simple graph is the symmetric sign matrix with zero
diagonal, $-1$ on adjacent pairs, and $+1$ on non-adjacent distinct pairs. Its
second spectral moment is graph-independent, $\tr(S^2) = n(n-1)$, giving the
universal energy bound $E_S \ge \sqrt{n(n-1)}$ but rendering the second moment
insensitive to local edits: deleting an edge leaves $\tr(S^2)$ unchanged. We prove
the companion fact that the third moment is sensitive, with an exact closed form.
An edge flip is a symmetric rank-two update $M \mapsto M + c\,(E^{ab} + E^{ba})$,
and for any real symmetric zero-diagonal $M$ and $a \neq b$ we prove
$\tr((M+P)^3) - \tr(M^3) = 6c\,(M^2)_{ab}$. A Seidel edge deletion is the flip with
weight $c=2$, so the third Seidel moment changes by $12\,(S^2)_{ab}$ while the
second moment is invariant. We exhibit this on $K_3$ versus $K_3 - e = P_3$, where
$\tr(S^3)$ jumps from $-6$ to $+6$ while $\tr(S^2)$ stays fixed at $6$. Finally,
complementation negates the Seidel matrix and hence preserves Seidel energy, so
energy is not monotone in the number of edges.
\end{abstract}

\maketitle

\section{Introduction}

Spectral graph theory studies a graph through the eigenvalues of an associated
matrix. The \emph{Seidel matrix} $S$ encodes a graph by treating adjacency and
non-adjacency as equal and opposite $\pm 1$ signs. Its distinctive feature is a
large invariance group: graphs related by Seidel switching share the same Seidel
spectrum. The \emph{Seidel energy} $E_S = \sum_i |\lambda_i|$ is a scalar
invariant compressing the whole spectrum, and it satisfies the universal bound
$E_S \ge \sqrt{n(n-1)}$.

This paper isolates a precise sense in which the low moments fail to see local
structure and repairs the failure at the third moment. Our contributions are: a
closed-form formula for the third-moment change of a symmetric zero-diagonal
matrix under a rank-two flip (Theorem~\ref{thm:flip}); the identification of Seidel
edge deletion with the flip of weight $c=2$ (Theorem~\ref{thm:delete}); the
resulting $12\,(S^2)_{ab}$ change of the third moment (Theorem~\ref{thm:cube})
against the invariant second moment (Theorem~\ref{thm:sq}); an explicit minimal
witness (Section~\ref{sec:witness}); and the proof that complementation preserves
Seidel energy, refuting monotonicity in edge count (Section~\ref{sec:compl}).

\section{Definitions}

Let $V$ be a finite vertex set with $|V| = n$; all matrices are indexed by $V$ over
$\R$. For a symmetric adjacency relation $\adj$ define the \emph{Seidel matrix}
$S = S(\adj)$ by
\[
S_{ij} =
\begin{cases}
\;\;0 & i = j,\\
-1 & i \neq j,\ \adj\,i\,j,\\
+1 & i \neq j,\ \neg\,\adj\,i\,j.
\end{cases}
\]
Then $S$ is real symmetric with zero diagonal, hence Hermitian with $n$ real
eigenvalues $\lambda_1, \dots, \lambda_n$. The $k$-th spectral moment is
$\mu_k = \sum_i \lambda_i^k = \tr(S^k)$, and the Seidel energy is
$E_S = \sum_i |\lambda_i|$. For positions $a,b$ let $E^{ab}$ be the matrix unit
with a $1$ in position $(a,b)$; the \emph{flip perturbation} of weight $c$ at
$\{a,b\}$ is $P = P_{ab}(c) = c\,(E^{ab} + E^{ba})$. The complement relation is
$\overline{\adj}\,i\,j \iff (i \neq j \wedge \neg\,\adj\,i\,j)$.

\section{Foundational moment identities}

\begin{proposition}[First moment]
$\tr(S) = 0$.
\end{proposition}
\begin{proof}
The diagonal of $S$ is identically zero.
\end{proof}

\begin{proposition}[Second moment is graph-independent]\label{prop:sq}
$\tr(S^2) = n(n-1)$ for every graph on $n$ vertices.
\end{proposition}
\begin{proof}
By symmetry $(S^2)_{ii} = \sum_j S_{ij}^2 = n-1$, since each off-diagonal entry is
$\pm 1$ and the diagonal is $0$. Summing over $i$ gives $n(n-1)$, independent of
adjacency.
\end{proof}

\begin{corollary}[Universal energy floor]
For every graph on $n \ge 1$ vertices, $E_S \ge \sqrt{n(n-1)}$.
\end{corollary}
\begin{proof}
$\big(\sum_i |\lambda_i|\big)^2 = \sum_i \lambda_i^2 + 2\sum_{i<j}
|\lambda_i||\lambda_j| \ge \sum_i \lambda_i^2 = n(n-1)$ by
Proposition~\ref{prop:sq}.
\end{proof}

\begin{remark}[Switching invariance]
Seidel switching conjugates $S$ by a diagonal $\pm 1$ matrix, preserving the
spectrum, all moments, and the energy.
\end{remark}

\section{The third-moment edge-flip formula}

\begin{lemma}[Cubic trace expansion]\label{lem:cube}
For any matrices $M,P$,
\[
\tr((M+P)^3) = \tr(M^3) + 3\tr(M^2 P) + 3\tr(M P^2) + \tr(P^3).
\]
\end{lemma}
\begin{proof}
Expand and collect the eight products using cyclicity $\tr(XY) = \tr(YX)$; the
three single-$P$ products have equal trace, as do the three single-$M$ products.
\end{proof}

\begin{lemma}[Trace against a matrix unit]\label{lem:single}
For any matrix $A$ and scalar $r$, $\tr\big(A\,(r E^{ab})\big) = r\,A_{ba}$.
\end{lemma}
\begin{proof}
$\big(A\,(rE^{ab})\big)_{ii} = r\,A_{ia}\,[b=i]$; sum the diagonal.
\end{proof}

\begin{theorem}[Third-moment change under a flip]\label{thm:flip}
Let $M$ be real symmetric with $M_{ii} = 0$ for all $i$, let $a \neq b$, and let
$c \in \R$. With $P = c\,(E^{ab}+E^{ba})$,
\[
\tr\big((M+P)^3\big) - \tr(M^3) = 6\,c\,(M^2)_{ab}.
\]
\end{theorem}
\begin{proof}
By Lemma~\ref{lem:cube} the change is $3\tr(M^2 P) + 3\tr(M P^2) + \tr(P^3)$. Now
$P^2 = c^2(E^{aa}+E^{bb})$ is diagonal, so $\tr(P^3)$ has zero diagonal support and
vanishes, and $\tr(M P^2) = c^2(M_{aa}+M_{bb}) = 0$ by the zero-diagonal
hypothesis. By Lemma~\ref{lem:single} and symmetry of $M^2$,
$\tr(M^2 P) = c[(M^2)_{ba} + (M^2)_{ab}] = 2c\,(M^2)_{ab}$. Hence the change is
$6c\,(M^2)_{ab}$.
\end{proof}

\section{Edge deletion as a weight-two flip}

\begin{theorem}[Edge deletion is a flip with $c=2$]\label{thm:delete}
If $\adj$ and $\adj'$ agree on every pair except $\{a,b\}$, which is an edge of
$\adj$ but not of $\adj'$, then
\[
S(\adj') = S(\adj) + 2\,(E^{ab}+E^{ba}) = S(\adj) + P_{ab}(2).
\]
\end{theorem}
\begin{proof}
Off $\{a,b\}$ the matrices agree; at $(a,b)$ and $(b,a)$ the Seidel entry moves
from $-1$ (adjacent) to $+1$ (non-adjacent), a change of $+2$.
\end{proof}

\begin{theorem}[Second moment invariant]\label{thm:sq}
For any two graphs on the same vertex set,
$\tr(S(\adj')^2) = \tr(S(\adj)^2)$.
\end{theorem}
\begin{proof}
Both equal $n(n-1)$ by Proposition~\ref{prop:sq}.
\end{proof}

\begin{theorem}[Third moment detects deletion]\label{thm:cube}
Under the hypotheses of Theorem~\ref{thm:delete},
\[
\tr\big(S(\adj')^3\big) - \tr\big(S(\adj)^3\big) = 12\,(S(\adj)^2)_{ab}.
\]
\end{theorem}
\begin{proof}
Apply Theorem~\ref{thm:flip} to $M = S(\adj)$ (symmetric, zero diagonal) with
$c = 2$: $6\cdot 2\cdot (S^2)_{ab} = 12\,(S^2)_{ab}$.
\end{proof}

\begin{remark}
The controlling quantity $(S^2)_{ab} = \sum_{k} S_{ak}S_{kb}$ is a signed
common-neighbour count: $+1$ for each vertex agreeing on $\{a,b\}$ and $-1$ for
each disagreeing. It is generically nonzero, which is exactly why the third moment
sees an edit invisible to the sphere constraint $\sum_i \lambda_i^2 = n(n-1)$.
\end{remark}

\section{A minimal witness: $K_3$ versus $P_3$}\label{sec:witness}

For the triangle $K_3$ on $\{1,2,3\}$,
\[
S(K_3) = \begin{pmatrix} 0 & -1 & -1 \\ -1 & 0 & -1 \\ -1 & -1 & 0 \end{pmatrix},
\qquad
S(P_3) = \begin{pmatrix} 0 & -1 & -1 \\ -1 & 0 & +1 \\ -1 & +1 & 0 \end{pmatrix}.
\]
Direct computation gives $\tr(S^2) = 6$ for both, while $\tr(S^3)$ jumps from $-6$
(for $K_3$) to $+6$ (for $P_3$), a change of $+12$. The formula predicts this
exactly: $(S(K_3)^2)_{23} = S_{21}S_{13} = (-1)(-1) = 1$, so the change is
$12 \cdot 1 = 12$.

\section{Complementation and non-monotonicity of energy}\label{sec:compl}

\begin{theorem}[Complementation negates the Seidel matrix]
$S(\overline{\adj}) = -\,S(\adj)$.
\end{theorem}
\begin{proof}
The diagonal is $0$ on both sides; off the diagonal, complementation exchanges
adjacency and non-adjacency, negating each entry.
\end{proof}

\begin{theorem}[Energy is negation-invariant]
For any Hermitian $A$, $E(-A) = E(A)$, where $E$ is the sum of absolute values of
eigenvalues.
\end{theorem}
\begin{proof}
The eigenvalues of $-A$ are the negatives of those of $A$, and $|-\lambda| =
|\lambda|$. Equivalently, the characteristic polynomials of $A$ and $-A$ are
related by $x \mapsto -x$ up to sign, so the multiset of absolute values of roots
is unchanged.
\end{proof}

\begin{corollary}
$E_S(\overline{G}) = E_S(G)$ for every graph $G$; hence $E_S$ is not a monotone
function of the number of edges.
\end{corollary}
\begin{proof}
Combine the previous two theorems. A graph and its complement have edge counts
summing to $\binom{n}{2}$ yet identical Seidel energy.
\end{proof}

\section{Discussion and future work}

Compressing a spectrum into a few moments buys tractability at the cost of
resolution: the second Seidel moment is powerful precisely because it is constant,
yet that constancy blinds it to local edits, which the third moment resolves
cleanly thanks to the zero diagonal. Natural extensions include: determining the
sign of $(S^2)_{ab}$ on Turán graphs toward a strict edge-deletion inequality;
converting the third-moment change plus the fixed second moment into an
eigenvalue-counting statement about mass crossing zero; computing the fourth-moment
response $\tr((M+P)^4) - \tr(M^4)$; establishing switching-class energy
monotonicity via majorization on the sphere $\sum_i \lambda_i^2 = n(n-1)$; and
proving that the universal floor is asymptotically sharp only for conference
two-graphs.

\end{document}

