"""Demo: the low spectral moments of the Seidel matrix."""
from __future__ import annotations
from itertools import combinations
from typing import Iterable
import numpy as np

def seidel_matrix(n: int, edges: Iterable[tuple[int, int]]) -> np.ndarray:
    """n x n Seidel matrix: 0 on diagonal, -1 on edges, +1 on non-edges."""
    edge_set = {frozenset(e) for e in edges}
    S = np.ones((n, n)); np.fill_diagonal(S, 0.0)
    for i, j in combinations(range(n), 2):
        S[i, j] = S[j, i] = -1.0 if frozenset((i, j)) in edge_set else 1.0
    return S

def moment(S: np.ndarray, k: int) -> float:
    return float(np.trace(np.linalg.matrix_power(S, k)))

if __name__ == "__main__":
    for name, (n, E) in {
        "K3": (3, [(0,1),(0,2),(1,2)]),
        "C5": (5, [(0,1),(1,2),(2,3),(3,4),(4,0)]),
        "K4": (4, list(combinations(range(4), 2))),
    }.items():
        S = seidel_matrix(n, E)
        print(f"{name}: tr(S)={moment(S,1):.0f}  tr(S^2)={moment(S,2):.0f}  "
              f"n(n-1)={n*(n-1)}")

"""Demo: complementation negates S and preserves Seidel energy."""
from __future__ import annotations
from itertools import combinations
from typing import Iterable
import numpy as np

def seidel_matrix(n: int, edges: Iterable[tuple[int, int]]) -> np.ndarray:
    edge_set = {frozenset(e) for e in edges}
    S = np.ones((n, n)); np.fill_diagonal(S, 0.0)
    for i, j in combinations(range(n), 2):
        S[i, j] = S[j, i] = -1.0 if frozenset((i, j)) in edge_set else 1.0
    return S

def energy(S: np.ndarray) -> float:
    return float(np.sum(np.abs(np.linalg.eigvalsh(S))))

def complement(n: int, edges: Iterable[tuple[int, int]]) -> list[tuple[int, int]]:
    es = {frozenset(e) for e in edges}
    return [(i, j) for i, j in combinations(range(n), 2) if frozenset((i, j)) not in es]

if __name__ == "__main__":
    for name, (n, E) in {
        "P4": (4, [(0,1),(1,2),(2,3)]),
        "C5": (5, [(0,1),(1,2),(2,3),(3,4),(4,0)]),
    }.items():
        S = seidel_matrix(n, E); Sc = seidel_matrix(n, complement(n, E))
        print(f"{name}: S(compl)=-S? {np.allclose(Sc, -S)}  "
              f"E(G)={energy(S):.4f}  E(compl)={energy(Sc):.4f}")

