function SPECTRAL-MOMENTS(n, edges, kmax):
    S <- n x n matrix of zeros
    for each unordered pair {i,j}, i != j:
        S[i][j] <- S[j][i] <- (-1 if {i,j} in edges else +1)
    P <- identity(n); moments <- []
    for t in 1..kmax:
        P <- P * S          # now P = S^t
        append trace(P) to moments
    return moments

function SEIDEL-ENERGY(S):
    lambda <- eigenvalues of symmetric S
    return sum of |lambda_i|

function ENERGY-FLOOR(n):
    return sqrt(n * (n - 1))

function ENERGY-RATIO(n, edges):
    S <- Seidel matrix of (n, edges)
    return SEIDEL-ENERGY(S) / ENERGY-FLOOR(n)   # always >= 1

